def generateString(str1: str, str2: str) -> str:
    n, m = len(str1), len(str2)
    N = n + m - 1
    word = [None] * N

    # Place str2 for every 'T' window, detecting conflicts.
    for i, c in enumerate(str1):
        if c == 'T':
            for j in range(m):
                p = i + j
                if word[p] is None:
                    word[p] = str2[j]
                elif word[p] != str2[j]:
                    return ""

    fixed = [w is not None for w in word]
    word = [w if w is not None else 'a' for w in word]

    # Repair 'F' windows that currently equal str2.
    for i, c in enumerate(str1):
        if c == 'F' and ''.join(word[i:i + m]) == str2:
            for p in range(i + m - 1, i - 1, -1):
                if not fixed[p]:
                    word[p] = 'b'
                    break
            else:
                return ""

    return ''.join(word)
